# build_v10.py
import base64, os

files = {}

# UTILS/OLLAMA_CLIENT.PY - fix extract_confidence para coger ULTIMA ocurrencia
files['utils/ollama_client.py'] = base64.b64decode('').decode('utf-8')

for path, content in files.items():
    os.makedirs(os.path.dirname(path) if os.path.dirname(path) else '.', exist_ok=True)
    mode = 'wb' if isinstance(content, bytes) else 'w'
    enc  = {} if isinstance(content, bytes) else {'encoding': 'utf-8'}
    with open(path, mode, **enc) as f:
        f.write(content)
    print('Written: ' + path)

print('Done')